use vstd::prelude::*;

verus! {
    /// Rotates a non-empty vector of u32s to the right by `n` positions.
    /// The rotation amount `n` is taken modulo the vector length.
    /// If `len = list.len()` and `k = n % len`, then the result is
    /// exactly `list[len-k .. len] ++ list[0 .. len-k]`.
    fn rotate_right(list: &Vec<u32>, n: usize) -> (new_list: Vec<u32>)
        requires list.len() > 0
        ensures new_list.len() == list.len()
        ensures forall(|i: usize| i < list.len() ==>
            // new_list[i] == list[(len - k + i) % len]
            new_list[i] == list[(list.len() - (n % list.len()) + i) % list.len()])
    {
        let len = list.len();
        let k = n % len;
        let s = len - k; // starting index in the original list

        // Build the rotated vector by pushing elements in order
        let mut new_list = Vec::with_capacity(len);
        let mut i = 0;
        while i < len {
            invariant i <= len;
            invariant new_list.len() == i;
            invariant forall(|j: usize| j < i ==>
                // for all already-pushed indices j,
                // new_list[j] == list[(s + j) % len]
                new_list[j] == list[(s + j) % len]);
            decreases len - i;
            {
                new_list.push(list[(s + i) % len]);
                i += 1;
            }
        }

        new_list
    }
}